import{z as s,x as i,o as e,c as o,q as B,j as l,D as a,d as r,s as A,S as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"跨语言迁移","description":"","frontmatter":{"title":"跨语言迁移","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ml-crosslingual-transfer.md","filePath":"llm/ml-crosslingual-transfer.md","lastUpdated":1791063341000}'),p={name:"llm/ml-crosslingual-transfer.md"};function C(d,E,m,D,F,h){const t=i("Mermaid");return e(),o("div",null,[E[2]||(E[2]=B('<h1 id="跨语言迁移" tabindex="-1">跨语言迁移 <a class="header-anchor" href="#跨语言迁移" aria-label="Permalink to &quot;跨语言迁移&quot;">​</a></h1><div class="epigraph"><p>迁移不是翻译：模型可以把两门语言的词面对齐到同一片表征里，但把这片表征当成翻译器用，就会在语序与知识密度上摔跤。</p><footer>—— 据 Pires 等 2019、Conneau 等 2020、Wendler 等 2024 整理</footer></div><p><a href="/llm/ml-tokenizer-multilingual">上一课</a>把分词的工程账算清：名额、块长、形式三本账，fertility 表当诊断仪。但 fertility 只保证「切法便宜」，不保证切出来的子词在表征里语义对齐——中文与英文的「银行」可以都切成便宜的好块，却落进不相干的表征区域。本课写零样本跨语言迁移的机制：为什么共享词表能带来迁移，迁移在哪里失效，什么时候该退回翻译管道。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>预训练语料里混了中英文，模型没做过中文指令微调，却往往能答中文问题——这就是零样本跨语言迁移。mBERT 一类模型最先给出系统证据：只用英语或联合语料训练，零样本 XNLI 上非英语仍可用（Pires 等 2019；Wu &amp; Dredze 2019）。但迁移高度不均匀：与英语语序接近的语言跌分少，语序差异大的语言跌分多；分类任务迁移好，生成任务与知识密集任务迁移差。</p><p><span class="marginnote">术语翻译：零样本（zero-shot）就是「没专门教过也能上手」。类比：一个只受英语训练的学生，看到中文数学题仍可能做对——因为数字、公式这类「锚点」是共享的，题面词汇靠上下文猜。迁移好坏取决于这类共享锚点有多少，而不是翻译能力。</span></p><p>缺口在于：切法共享只是必要条件。两门语言的同义子词要在表征里汇聚，任务语义要跨语言泛化，生成时还要能切回目标语言的表面形式。三步里任何一步断裂，迁移就退化成「英语模型的中文界面」——看起来能对话，规划与判断都在英语侧发生。</p><h3 id="机制假设有两条" tabindex="-1">机制假设有两条 <a class="header-anchor" href="#机制假设有两条" aria-label="Permalink to &quot;机制假设有两条&quot;">​</a></h3><p>词汇正交说：联合语料里的跨语言同现——人名、数字、实体、代码切换文本——把不同语言的子词嵌进同一语义空间，实体是天然锚点。潜语言说：生成侧的证据指向模型中间层倾向以英语为枢纽，先在潜空间里规划，再映射回目标语言表面形式（Wendler 等 2024）。两条不互斥：前者解释编码侧对齐，后者解释解码侧为什么常出现「中文问题、英文推理链」。</p>',9)),(e(),l(n,null,{default:a(()=>[A(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E4%B8%AD%E6%96%87%E8%BE%93%E5%85%A5%22%5D%20--%3E%20ENC%5B%22%E7%BC%96%E7%A0%81%EF%BC%9A%E5%AD%90%E8%AF%8D%E6%B1%87%E8%81%9A%E5%88%B0%E5%85%B1%E4%BA%AB%E8%AF%AD%E4%B9%89%E7%A9%BA%E9%97%B4%22%5D%0A%20%20ENC%20--%3E%20MID%5B%22%E4%B8%AD%E5%B1%82%E6%BD%9C%E8%A1%A8%E7%A4%BA%EF%BC%9A%E5%80%BE%E5%90%91%E8%8B%B1%E8%AF%AD%E6%9E%A2%E7%BA%BD%22%5D%0A%20%20MID%20--%3E%20DEC%5B%22%E8%A7%A3%E7%A0%81%EF%BC%9A%E6%98%A0%E5%B0%84%E5%9B%9E%E7%9B%AE%E6%A0%87%E8%AF%AD%E8%A8%80%E8%A1%A8%E9%9D%A2%E5%BD%A2%E5%BC%8F%22%5D%0A%20%20MID%20--%3E%20ENDEC%5B%22%E8%8B%B1%E6%96%87%E8%A1%A8%E9%9D%A2%E5%BD%A2%E5%BC%8F%EF%BC%9A%E6%B7%B7%E6%9D%82%E6%88%96%E9%80%80%E5%8C%96%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程上有四条迁移路径，按干预强度排序。零样本：什么都不做，靠预训练对齐；诊断价值最高，生产风险也最高。翻译测试（translate-test）：输入先译成英语、答案再译回，把跨语言问题交给翻译管道；质量上限取决于翻译系统，延迟与成本翻倍。翻译训练（translate-train）：把英语指令数据机译成目标语言再做微调，XLM 时代的经典配方（Conneau &amp; Lample 2019），便宜但继承翻译腔。平行对齐：训练时用翻译语言建模一类目标对齐平行句，或用双语词典做正则；效果最持久，数据最贵。</p><p>推理侧还有一条便宜路径：思维链语言选择。MGSM 的结果显示，模型用高资源语言写推理链、再用题目语言作答，能显著提升低资源数学题表现（Shi 等 2022）——这正是潜语言假设的工程化利用。允许模型自选推理语言时，要处理<a href="/llm/language-mixing-reasoning">语言混杂</a>：混杂可能是能力也可能是失控，评测里分开计数。</p><p><span class="marginnote">Pires 等 2019 的反直觉结论：mBERT 对从未见过的中文句子做零样本 NLI 可用，但与英语语序差异越大的语言，迁移质量系统性越低——共享词表买来的对齐自带类型学偏向。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>四条路径对应的干预点不同。零样本只依赖编码侧汇聚，所以分类任务（浅层语义）最好、生成任务最差；translate-test 把整条链搬到英语侧，目标语言只剩表面形式生成，质量受限于翻译而不是模型；translate-train 干预指令层，让任务语义以目标语言为载体，但语料是翻译体，文风与语用被源语言语法渗入；平行对齐直接加强汇聚本身，是唯一触及机制的做法。诊断用探针而不是猜测：问目标语言的本地知识（只有目标语料里有）与跨语言可借的知识（英语语料里有），两题的表现差就是「迁移管道化」的程度。</p>',6)),(e(),l(n,null,{default:a(()=>[A(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20IN%5B%22%E7%9B%AE%E6%A0%87%E8%AF%AD%E8%A8%80%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20Z%5B%22%E9%9B%B6%E6%A0%B7%E6%9C%AC%EF%BC%9A%E7%9B%B4%E6%8E%A5%E8%BF%9B%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20IN%20--%3E%20TT%5B%22translate-test%EF%BC%9A%E5%85%88%E8%AF%91%E8%8B%B1%EF%BC%8C%E7%AD%94%E5%90%8E%E8%AF%91%E5%9B%9E%22%5D%0A%20%20IN%20--%3E%20TR%5B%22translate-train%EF%BC%9A%E8%8B%B1%E8%AF%AD%E6%8C%87%E4%BB%A4%E9%A2%84%E8%AF%91%E5%90%8E%E5%BE%AE%E8%B0%83%22%5D%0A%20%20IN%20--%3E%20PA%5B%22%E5%B9%B3%E8%A1%8C%E5%AF%B9%E9%BD%90%EF%BC%9A%E8%AE%AD%E7%BB%83%E6%97%B6%E5%AF%B9%E9%BD%90%E5%B9%B3%E8%A1%8C%E5%8F%A5%22%5D%0A%20%20Z%20--%3E%20Q1%5B%22%E6%9C%80%E4%BE%BF%E5%AE%9C%EF%BC%8C%E7%94%9F%E4%BA%A7%E9%A3%8E%E9%99%A9%E6%9C%80%E9%AB%98%22%5D%0A%20%20TT%20--%3E%20Q2%5B%22%E8%B4%A8%E9%87%8F%E7%9C%8B%E7%BF%BB%E8%AF%91%E7%B3%BB%E7%BB%9F%EF%BC%8C%E5%BB%B6%E8%BF%9F%E6%88%90%E6%9C%AC%E7%BF%BB%E5%80%8D%22%5D%0A%20%20TR%20--%3E%20Q3%5B%22%E4%BE%BF%E5%AE%9C%EF%BC%8C%E4%BD%86%E7%BB%A7%E6%89%BF%E7%BF%BB%E8%AF%91%E8%85%94%22%5D%0A%20%20PA%20--%3E%20Q4%5B%22%E6%9C%80%E6%8C%81%E4%B9%85%EF%BC%8C%E6%95%B0%E6%8D%AE%E6%9C%80%E8%B4%B5%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">为什么重要：管道化迁移的模型并不是「学会了中文」，只是搭了一条通往英语能力的管道——它能答英语语料里有的知识，答不出只有中文语料才有的本地知识（本地法规、本土常识）。上线前用「本地知识 vs 可借知识」两道探针对测，一下就能看出迁移是真对齐还是空管道。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>迁移不搬运知识。中文语料里没有的本地法规、英语语料里有，翻译路径能借到；两边都没有的知识，任何迁移机制都变不出来——那是<a href="/llm/ml-low-resource">低资源语言</a>要处理的数据问题。迁移还会放大配比偏差：联合语料里英语占比过高时，任务规划、拒答边界、价值判断都发生在英语侧，评测要把这类「管道化迁移」单测出来。诊断也不能只看分类正确率：它掩盖语病与混杂，而用户看到的是表面形式质量；生成任务要配该语言的母语者人评。</p><p><span class="marginnote">常见误区：把「分词器对中文友好」（fertility 低）当成「中文能力好」。切得便宜只保证 token 数少；子词语义是否与英语对齐、生成是否通顺，是分词器管不到的后两步。评估多语能力要看生成质量与本地知识探针，不能只看分词账本。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>零样本迁移 = 编码侧子词汇聚 + 中层潜表示 + 解码侧表面形式映射；三步都可能断。</li><li>词汇正交与潜语言两条机制假设互补；「中文问题、英文推理链」是后者的可观察证据。</li><li>工程路径按干预强度排序：零样本、translate-test、translate-train、平行对齐；CoT 语言选择是便宜的推理侧杠杆。</li><li>迁移不搬运知识，知识缺口交给数据；管道化迁移要靠本地知识探针单测。</li><li>出处：Pires et al., ACL 2019；Wu &amp; Dredze, EMNLP 2019；Conneau &amp; Lample, NeurIPS 2019；Conneau et al., XLM-R, 2020；Shi et al., ICLR 2023；Wendler et al., 2024。</li></ul>',6))])}const c=s(p,[["render",C]]);export{_ as __pageData,c as default};
